function getFirstKCharacters($s, $k) {
    // Ensure k is not negative and does not exceed the string length
    if ($k < 0) {
        return "";
    }

    $length = strlen($s);
    if ($k >= $length) {
        return $s;
    }

    return substr($s, 0, $k);
}

